"""Dependency-free Ingress UI using the ACP/AEP visual language."""

ADMIN_CSS = r"""
:root{color-scheme:light;scrollbar-gutter:stable;--bg:#f3f6f9;--surface:#fff;--surface2:#edf3f7;--text:#17243a;--muted:#687b90;--line:#d8e2eb;--cyan:#058caf;--cyan-soft:#dff5fa;--good:#16845b;--shadow:0 5px 22px #1e3a5f12}
html[data-theme=dark]{color-scheme:dark;--bg:#0d1420;--surface:#172235;--surface2:#202c41;--text:#e7edf5;--muted:#a4b2c6;--line:#30415d;--cyan:#52c9e6;--cyan-soft:#173b4a;--good:#50c895;--shadow:none}
*{box-sizing:border-box}[hidden]{display:none!important}body{font:15px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--text);margin:0}body.drawer-open{overflow:hidden}.app{max-width:1840px;margin:auto;padding:22px clamp(18px,2.8vw,48px) 40px}.site-header{margin-bottom:28px}.header-main{display:flex;align-items:center;gap:20px;min-height:58px}.brand{display:flex;align-items:center;gap:11px;color:var(--cyan);text-decoration:none;font-size:24px;font-weight:800;letter-spacing:-.02em}.brand img{width:46px;height:46px;object-fit:contain;filter:drop-shadow(0 4px 8px #102a4330)}.brand b{font-size:13px;color:var(--muted);font-weight:650;white-space:nowrap}.header-actions{display:flex;gap:8px;margin-left:auto}.switch,.secondary{color:var(--text);padding:9px 12px;border-radius:7px;border:1px solid var(--line);background:var(--surface);font:inherit;cursor:pointer}.nav-scroll{margin-top:12px;overflow-x:auto}.nav{display:flex;gap:5px;width:max-content;min-width:100%}.nav a{color:var(--text);text-decoration:none;padding:9px 12px;border-radius:7px}.nav a.active{background:var(--cyan-soft);color:var(--cyan);font-weight:700}.view{display:none}.view.active{display:block}.pagehead{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:4px 0 20px}.pagehead h1{font-size:29px;margin:0 0 5px;letter-spacing:-.025em}.pagehead p{margin:0;color:var(--muted)}.primary{color:#fff;background:var(--cyan);padding:10px 14px;border-radius:7px;border:0;font:inherit;font-weight:700;white-space:nowrap;cursor:pointer}.metrics{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));gap:12px}.card,.metric{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px;box-shadow:var(--shadow)}.metric{position:relative;overflow:hidden}.metric:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--cyan)}.metric strong{display:block;font-size:25px;line-height:1.2}.metric span{display:block;color:var(--muted);margin-top:5px}.notice{margin-top:16px}.notice h2{font-size:19px;margin:0 0 7px}.notice p{margin:0;color:var(--muted);line-height:1.55}.state{display:inline-flex;align-items:center;gap:8px;color:var(--good);font-weight:700}.state:before{content:"";width:9px;height:9px;border-radius:50%;background:currentColor}.drawer-shell{position:fixed;inset:0;z-index:1000}.drawer-overlay{position:absolute;inset:0;background:#07132180;backdrop-filter:blur(2px)}.drawer{position:absolute;inset:0 0 0 auto;width:min(520px,calc(100vw - 36px));background:var(--surface);border-left:1px solid var(--line);box-shadow:-18px 0 45px #07132135;display:flex;flex-direction:column;outline:0}.drawer-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;padding:22px 24px;border-bottom:1px solid var(--line)}.drawer-head h2{margin:0;font-size:22px}.drawer-close{font-size:22px;line-height:1;padding:8px 11px}.drawer-body{padding:24px;overflow:auto}.drawer-body p{color:var(--muted);line-height:1.6}.drawer-body dl{display:grid;grid-template-columns:auto 1fr;gap:10px 16px}.drawer-body dt{font-weight:700}.drawer-body dd{margin:0;color:var(--muted)}
@media(max-width:850px){.app{padding:16px}.nav-scroll{margin-inline:-16px;padding-inline:16px}.metrics{grid-template-columns:1fr}.pagehead{align-items:flex-start;flex-direction:column}}@media(max-width:560px){.brand{font-size:19px}.brand img{width:40px;height:40px}.header-main{align-items:flex-start}.header-actions{flex-direction:column}.pagehead h1{font-size:25px}.drawer{width:100vw}.drawer-body dl{grid-template-columns:1fr;gap:4px}.drawer-body dd{margin-bottom:8px}}
"""

ADMIN_JS = r"""
const app=document.querySelector('.app'),base=app.dataset.base;
let language=localStorage.getItem('mcb-language')||((navigator.language||'fr').toLowerCase().startsWith('fr')?'fr':'en');
let theme=localStorage.getItem('mcb-theme')||((matchMedia('(prefers-color-scheme: dark)').matches)?'dark':'light');
const I18N={fr:{overview:'Vue d’ensemble',clients:'Clients MCP',targets:'Cibles',ssh:'Capacités SSH',web:'Cibles Web',sessions:'Sessions',overviewTitle:'Vue d’ensemble',overviewIntro:'État réel du socle MCP Capability Bridge.',statusAction:'Voir le statut',appState:'Application',publicSurface:'Surface publique',database:'Base de données',ready:'Prête',healthOnly:'Santé uniquement',generation:'Génération 1',foundationTitle:'Socle opérationnel',foundationText:'Les deux surfaces HTTP partagent un seul runtime. Aucun endpoint MCP, client, credential, cible ou adaptateur n’est disponible dans le Lot 0.',plannedTitle:'Fonction prévue dans un lot ultérieur',plannedText:'Cette vue réserve la navigation de la suite sans simuler une fonctionnalité non encore implémentée.',drawerTitle:'Statut du Bridge',close:'Fermer',runtime:'Runtime',listeners:'Listeners',scope:'Périmètre',singleRuntime:'Processus unique',listenerValues:'8099 Ingress · 8098 santé',scopeValue:'Lot 0 uniquement',changeLanguage:'Passer en anglais',changeTheme:'Changer de thème'},en:{overview:'Overview',clients:'MCP clients',targets:'Targets',ssh:'SSH capabilities',web:'Web targets',sessions:'Sessions',overviewTitle:'Overview',overviewIntro:'Actual MCP Capability Bridge foundation status.',statusAction:'View status',appState:'Application',publicSurface:'Public surface',database:'Database',ready:'Ready',healthOnly:'Health only',generation:'Generation 1',foundationTitle:'Operational foundation',foundationText:'Both HTTP surfaces share one runtime. No MCP endpoint, client, credential, target or adapter is available in Lot 0.',plannedTitle:'Feature planned for a later lot',plannedText:'This view reserves the suite navigation without simulating a feature that has not been implemented.',drawerTitle:'Bridge status',close:'Close',runtime:'Runtime',listeners:'Listeners',scope:'Scope',singleRuntime:'Single process',listenerValues:'8099 Ingress · 8098 health',scopeValue:'Lot 0 only',changeLanguage:'Switch to French',changeTheme:'Change theme'}};
function tr(key){return I18N[language][key]||key}
function apply(){document.documentElement.lang=language;document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-i18n]').forEach(node=>node.textContent=tr(node.dataset.i18n));document.querySelectorAll('[data-i18n-aria]').forEach(node=>node.ariaLabel=tr(node.dataset.i18nAria));document.getElementById('language').textContent=language==='fr'?'EN':'FR';document.getElementById('language').ariaLabel=tr('changeLanguage');document.getElementById('theme').textContent=theme==='dark'?'☀':'☾';document.getElementById('theme').ariaLabel=tr('changeTheme')}
function selectView(){const requested=location.hash.slice(1),allowed=['overview','clients','targets','ssh','web','sessions'],view=allowed.includes(requested)?requested:'overview';document.querySelectorAll('.view').forEach(node=>node.classList.toggle('active',node.id===view));document.querySelectorAll('.nav a').forEach(node=>node.classList.toggle('active',node.dataset.view===view))}
const shell=document.getElementById('drawer-shell'),drawer=document.getElementById('admin-drawer');let returnFocus=null;
function focusables(){return [...drawer.querySelectorAll('button:not([disabled]),a[href],[tabindex]:not([tabindex="-1"])')]}
function openDrawer(trigger){returnFocus=trigger||document.activeElement;shell.hidden=false;document.body.classList.add('drawer-open');requestAnimationFrame(()=>document.getElementById('drawer-close').focus())}
function closeDrawer(){if(shell.hidden)return;shell.hidden=true;document.body.classList.remove('drawer-open');returnFocus?.focus();returnFocus=null}
document.getElementById('status-open').onclick=event=>openDrawer(event.currentTarget);document.getElementById('drawer-close').onclick=closeDrawer;document.querySelector('.drawer-overlay').onclick=closeDrawer;
document.addEventListener('keydown',event=>{if(shell.hidden)return;if(event.key==='Escape'){event.preventDefault();closeDrawer();return}if(event.key!=='Tab')return;const items=focusables(),first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}});
document.getElementById('language').onclick=()=>{language=language==='fr'?'en':'fr';localStorage.setItem('mcb-language',language);apply()};document.getElementById('theme').onclick=()=>{theme=theme==='dark'?'light':'dark';localStorage.setItem('mcb-theme',theme);apply()};document.querySelectorAll('.nav a').forEach(link=>link.onclick=event=>{event.preventDefault();location.hash=link.dataset.view;selectView()});addEventListener('hashchange',selectView);apply();selectView();
"""
